SELECT analytics_budget_facts.cost_center, AVG(analytics_budget_facts.budget_variance_pct) AS budget_variance_pct FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2022 AND analytics_budget_facts.month = 9 AND analytics_budget_facts.department = 'department_11' AND analytics_budget_facts.expense_category = 'expense_01' GROUP BY analytics_budget_facts.cost_center ORDER BY budget_variance_pct DESC, analytics_budget_facts.cost_center ASC LIMIT 15
